template <typename FormatContext> struct format_tuple_element {
  using char_type = typename FormatContext::char_type;

  template <typename T>
  void operator()(const formatter<T, char_type>& f, const T& v) {
    if (i > 0) ctx.advance_to(detail::copy<char_type>(separator, ctx.out()));
    ctx.advance_to(f.format(v, ctx));
    ++i;
  }

  template <typename RangeFormatter, typename R>
  auto format_range(const RangeFormatter& rf, R&& range)
      -> typename FormatContext::iterator {
    range_mapper<buffered_context<char_type>> mapper;
    auto out = ctx.out();
    out = write<char_type>(out, rf.opening_bracket_);
    i = 0;
    auto it = range_begin(range);
    auto end = range_end(range);
    for (; it != end; ++it) {
      if (i > 0 && rf.has_separator_)
        out = write<char_type>(out, rf.separator_);
      ctx.advance_to(out);
      auto&& item = *it;
      out = rf.underlying_.format(mapper.map(item), ctx);
      ++i;
    }
    out = write<char_type>(out, rf.closing_bracket_);
    return out;
  }

  int i;
  FormatContext& ctx;
  basic_string_view<char_type> separator;
};

