 private:
  template <typename FormatContext>
  friend struct detail::format_tuple_element;

  detail::range_formatter_type<Char, T> underlying_;
  basic_string_view<Char> separator_ = detail::string_literal<Char, ',', ' '>{};
  bool has_separator_ = true;
  basic_string_view<Char> opening_bracket_ =
      detail::string_literal<Char, '['>{};
  basic_string_view<Char> closing_bracket_ =
      detail::string_literal<Char, ']'>{};
  bool is_string_ = false;
  bool is_debug_string_ = false;

 public:
  FMT_CONSTEXPR range_formatter() {}

  FMT_CONSTEXPR auto underlying() -> detail::range_formatter_type<Char, T>& {
    return underlying_;
  }

  FMT_CONSTEXPR void set_separator(basic_string_view<Char> sep) {
    separator_ = sep;
    has_separator_ = sep.size() != 0;
  }

  FMT_CONSTEXPR void set_brackets(basic_string_view<Char> open,
                                  basic_string_view<Char> close) {
    opening_bracket_ = open;
    closing_bracket_ = close;
  }

  template <typename ParseContext>
  FMT_CONSTEXPR auto parse(ParseContext& ctx) -> decltype(ctx.begin()) {
    auto it = ctx.begin();
    auto end = ctx.end();

    if (it != end && *it == 'n') {
      set_brackets({}, {});
      ++it;
    }

    if constexpr (std::is_same<T, Char>::value) {
      if (it != end && (*it == 's' || *it == '?')) {
        is_debug_string_ = (*it == '?');
        if (is_debug_string_) ++it;
        if (it == end || *it != 's')
          report_error("invalid format specifier");
        ++it;
        is_string_ = true;
        if (it != end && *it != '}')
          report_error("invalid format specifier");
        return it;
      }
    }

    if (it != end && *it != '}') {
      if (*it != ':') report_error("invalid format specifier");
      ++it;
    } else {
      detail::maybe_set_debug_format(underlying_, true);
    }

    ctx.advance_to(it);
    return underlying_.parse(ctx);
  }

  template <typename FormatContext>
  auto format_as_string(R range, FormatContext& ctx) const
      -> decltype(ctx.out()) {
    auto out = ctx.out();
    if (is_debug_string_) {
      detail::basic_memory_buffer<Char> buffer;
      for (auto it = range.begin(); it != range.end(); ++it)
        buffer.push_back(*it);
      out = detail::write_escaped_string<Char>(
          out, basic_string_view<Char>(buffer.data(), buffer.size()));
    } else {
      *out++ = static_cast<Char>('"');
      for (auto it = range.begin(); it != range.end(); ++it)
        *out++ = static_cast<Char>(*it);
      *out++ = static_cast<Char>('"');
    }
    ctx.advance_to(out);
    return out;
  }

  template <typename R, typename FormatContext>
  auto format(R&& range, FormatContext& ctx) const -> decltype(ctx.out()) {
    if constexpr (std::is_same<T, Char>::value) {
      if (is_string_) return format_as_string(range, ctx);
    }
    detail::format_tuple_element<FormatContext> writer{0, ctx, {}};
    return writer.format_range(*this, range);
  }
};

